:root {
  --reveal-duration: 1500ms;
  --reveal-stack: 50ms;
  --reveal-delay: 200ms;
}

/*

  Base reveal

*/
[data-reveal] {
  -webkit-transition-property: -webkit-transform;
  transition-property: -webkit-transform;
  transition-property: transform;
  transition-property: transform, -webkit-transform;
  -webkit-transition-duration: 1200ms;
          transition-duration: 1200ms;
  -webkit-transition-delay: 0ms;
          transition-delay: 0ms;
  -webkit-transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
          transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  will-change: transform;
  visibility: hidden;
  -webkit-transition-delay: var(--delay);
          transition-delay: var(--delay);
}
[data-reveal]:nth-child(1) {
  --delay: calc(var(--in-delay, 0) + 1 * 100ms);
}
[data-reveal]:nth-child(2) {
  --delay: calc(var(--in-delay, 0) + 2 * 100ms);
}
[data-reveal]:nth-child(3) {
  --delay: calc(var(--in-delay, 0) + 3 * 100ms);
}
[data-reveal]:nth-child(4) {
  --delay: calc(var(--in-delay, 0) + 4 * 100ms);
}
[data-reveal]:nth-child(5) {
  --delay: calc(var(--in-delay, 0) + 5 * 100ms);
}
[data-reveal]:nth-child(6) {
  --delay: calc(var(--in-delay, 0) + 6 * 100ms);
}
[data-reveal]:nth-child(7) {
  --delay: calc(var(--in-delay, 0) + 7 * 100ms);
}
[data-reveal]:nth-child(8) {
  --delay: calc(var(--in-delay, 0) + 8 * 100ms);
}
[data-reveal]:nth-child(9) {
  --delay: calc(var(--in-delay, 0) + 9 * 100ms);
}
[data-reveal]:nth-child(10) {
  --delay: calc(var(--in-delay, 0) + 10 * 100ms);
}
[data-reveal]:nth-child(11) {
  --delay: calc(var(--in-delay, 0) + 11 * 100ms);
}
[data-reveal]:nth-child(12) {
  --delay: calc(var(--in-delay, 0) + 12 * 100ms);
}
[data-reveal] {
  -webkit-transform: rotate(30deg) scale(0);
          transform: rotate(30deg) scale(0);
}

[data-reveal=opacity] {
  -webkit-transform: none;
          transform: none;
  opacity: 0;
}

[data-scroll]:not([data-scroll-ignore]).is-inview [data-reveal],
[data-scroll]:not([data-scroll-ignore]).is-inview[data-reveal],
[data-scroll][data-scroll-ignore].is-inview [data-tab-reveal][data-active] [data-reveal] {
  visibility: visible;
  -webkit-transform: none;
          transform: none;
  opacity: 1;
}

/*

  Reveal images

*/
[data-reveal-image] {
  clip-path: inset(0% 100% 0% 0%);
  -webkit-transition-property: clip-path;
  transition-property: clip-path;
  -webkit-transition-duration: 1200ms;
          transition-duration: 1200ms;
  -webkit-transition-delay: 0ms;
          transition-delay: 0ms;
  -webkit-transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
          transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  will-change: clip-path;
}

.is-inview[data-reveal-image],
.is-inview [data-reveal-image] {
  clip-path: inset(0% 0% 0% 0%);
}

/*

  Reveal text

*/
@-webkit-keyframes reveal-in {
  0% {
    -webkit-transform: translateY(1.5em);
            transform: translateY(1.5em);
    /*    transform: scaleX(0);*/
  }
  30% {
    color: rgba(var(--color-acc), 1);
  }
  100% {
    -webkit-transform: none;
            transform: none;
    color: rgba(var(--col), 1);
  }
}
