[data-toggles] [data-target] {
  clip-path: inset(0% 100% 0% 0%);
  tranform: none;
}
[data-toggles] [data-target].is-active {
  clip-path: inset(0% 0% 0% 0%);
}
[data-toggles] [data-target].is-opening {
  -webkit-animation: toggle-in 1200ms cubic-bezier(0.16, 1, 0.3, 1);
          animation: toggle-in 1200ms cubic-bezier(0.16, 1, 0.3, 1);
}
[data-toggles] [data-target].is-closing {
  clip-path: inset(0% 0% 0% 0%);
  -webkit-animation: toggle-out 1200ms cubic-bezier(0.16, 1, 0.3, 1);
          animation: toggle-out 1200ms cubic-bezier(0.16, 1, 0.3, 1);
  --reveal-delay: 0ms;
}
[data-toggles] [data-target]:not(.is-active) {
  /*    visibility: hidden;*/
}
[data-toggles] [data-hover-toggle], [data-toggles] [data-toggle] {
  --reveal-delay: 0ms;
  --reveal-duration: 600ms;
  -webkit-transition-property: opacity;
  transition-property: opacity;
  -webkit-transition-duration: 1200ms;
          transition-duration: 1200ms;
  -webkit-transition-delay: 0ms;
          transition-delay: 0ms;
  -webkit-transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
          transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  will-change: opacity;
}
[data-toggles] [data-hover-toggle]:not(.is-active), [data-toggles] [data-toggle]:not(.is-active) {
  opacity: 0.4;
}

