  -webkit-transform: none;
          transform: none;
  clip-path: initial;
  -webkit-filter: blur(calc(1em - var(--word-total) * 0.5 * 1em * (var(--progress) - (var(--word-index) + 0) / (var(--word-total) + 2))));
          filter: blur(calc(1em - var(--word-total) * 0.5 * 1em * (var(--progress) - (var(--word-index) + 0) / (var(--word-total) + 2))));
  opacity: calc(0 + var(--word-total) * 0.5 * 1 * (var(--progress) - (var(--word-index) + 0) / (var(--word-total) + 2)));
}
.meditation [data-reveal-progress] [data-char] {
  -webkit-transform: none;
          transform: none;
  clip-path: initial;
  -webkit-filter: blur(calc(1em - var(--char-total) * 1em * (var(--progress) - (var(--char-index) + 0) / (var(--char-total) / 2 + 1))));
          filter: blur(calc(1em - var(--char-total) * 1em * (var(--progress) - (var(--char-index) + 0) / (var(--char-total) / 2 + 1))));
  opacity: calc(0 + var(--char-total) * 1 * (var(--progress) - (var(--char-index) + 0) / (var(--char-total) / 2 + 1)));
}

.octagon {
  -webkit-transition-property: all;
  transition-property: all;
  -webkit-transition-duration: 1200ms;
          transition-duration: 1200ms;
  -webkit-transition-delay: 0ms;
          transition-delay: 0ms;
  -webkit-transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
          transition-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
  will-change: all;
  -webkit-transition-duration: 3s;
          transition-duration: 3s;
  -webkit-transform: scale(calc(0.8 + var(--trigger-in) * 0.2 - var(--trigger-out) * 0.2));
          transform: scale(calc(0.8 + var(--trigger-in) * 0.2 - var(--trigger-out) * 0.2));
  opacity: calc(0 + var(--trigger-in) * 1 - var(--trigger-out) * 1);
}
